-- Hindi translations are optional; existing English/Tamil content is preserved.
ALTER TABLE `pages`
  ADD COLUMN `titleHi` VARCHAR(255) NULL,
  ADD COLUMN `summaryHi` TEXT NULL,
  ADD COLUMN `bodyHi` LONGTEXT NULL;

ALTER TABLE `announcements`
  ADD COLUMN `titleHi` VARCHAR(255) NULL,
  ADD COLUMN `summaryHi` TEXT NULL,
  ADD COLUMN `bodyHi` LONGTEXT NULL,
  ADD COLUMN `footerMessageHi` VARCHAR(500) NULL,
  ADD COLUMN `wishesHi` TEXT NULL,
  ADD COLUMN `ctaLabelHi` VARCHAR(120) NULL;

ALTER TABLE `events`
  ADD COLUMN `titleHi` VARCHAR(255) NULL,
  ADD COLUMN `summaryHi` TEXT NULL,
  ADD COLUMN `bodyHi` LONGTEXT NULL,
  ADD COLUMN `categoryHi` VARCHAR(120) NULL,
  ADD COLUMN `locationHi` VARCHAR(255) NULL;

ALTER TABLE `media`
  ADD COLUMN `altHi` VARCHAR(255) NULL,
  ADD COLUMN `descriptionHi` TEXT NULL;

ALTER TABLE `activity_categories`
  ADD COLUMN `titleHi` VARCHAR(160) NULL;

ALTER TABLE `activities`
  ADD COLUMN `titleHi` VARCHAR(255) NULL,
  ADD COLUMN `summaryHi` TEXT NULL;

ALTER TABLE `galleries`
  ADD COLUMN `titleHi` VARCHAR(255) NULL,
  ADD COLUMN `summaryHi` TEXT NULL;

ALTER TABLE `fees`
  ADD COLUMN `titleHi` VARCHAR(255) NULL;

ALTER TABLE `honours`
  ADD COLUMN `nameHi` VARCHAR(160) NULL,
  ADD COLUMN `titleHi` VARCHAR(255) NULL,
  ADD COLUMN `descriptionHi` TEXT NULL;

ALTER TABLE `staff_members`
  ADD COLUMN `nameHi` VARCHAR(160) NULL,
  ADD COLUMN `designationHi` VARCHAR(200) NULL,
  ADD COLUMN `descriptionHi` TEXT NULL;

ALTER TABLE `toppers`
  ADD COLUMN `nameHi` VARCHAR(160) NULL;

